cards.solution:
function buatTabungan() {
  let saldo = 0;
  return jumlah => {
    saldo += jumlah;
    return saldo;
  };
}
const setor = buatTabungan();
setor(5000);
console.log(`Saldo: ${setor(3000)}`);
